/// <reference types="vitest/config" />
import { defineConfig, type Plugin } from 'vite';
import { MESSAGES, type MessageId } from './src/messages';

/** Replaces %M-n% placeholders in index.html with catalogue text, so messages.ts stays the single source. */
function catalogueHtml(): Plugin {
  return {
    name: 'catalogue-html',
    transformIndexHtml(html) {
      return html.replace(/%(M-\d+)%/g, (placeholder, id: string) => {
        if (!(id in MESSAGES)) throw new Error(`index.html: unknown message ${placeholder}`);
        return escapeHtml(MESSAGES[id as MessageId]);
      });
    },
  };
}

function escapeHtml(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ADR-008: relative base so the same build works from `vite preview` and any GitHub Pages sub-path.
export default defineConfig({
  base: './',
  plugins: [catalogueHtml()],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
  preview: {
    host: '127.0.0.1',
    port: 4173,
    strictPort: true,
  },
  // ADR-005: Vitest runs pure modules only, in the node environment.
  test: {
    environment: 'node',
    include: ['tests/unit/**/*.test.ts'],
  },
});
import { defineConfig, devices } from '@playwright/test';

const PORT = 4173;
const BASE_URL = `http://127.0.0.1:${PORT}/`;
const isCI = Boolean(process.env['CI']);

// ADR-005: e2e runs against the production build served by `vite preview`.
export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: true,
  forbidOnly: isCI,
  retries: 0, // never mask failures with retries, locally or in CI
  // CI also writes a JSON report; scripts/ci-summary.mjs turns it into per-engine check annotations.
  reporter: isCI
    ? [['list'], ['html', { open: 'never' }], ['json', { outputFile: 'test-results/e2e-results.json' }]]
    : 'list',
  use: {
    baseURL: BASE_URL,
    trace: 'retain-on-failure',
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } },
  ],
  webServer: {
    command: `npm run build && npm run preview -- --host 127.0.0.1 --port ${PORT} --strictPort`,
    url: BASE_URL,
    reuseExistingServer: !isCI,
    timeout: 120_000,
  },
});
